ther.parent = a.other;\n\n    expect(deepEqual(a, b)).toBeFalsy();\n  });\n\n  it('should not treat different values as equal when one side reuses an object reference', () => {\n    const shared = { value: 1 };\n\n    expect(\n      deepEqual(\n        { first: shared, second: shared },\n        { first: { value: 1 }, second: { value: 2 } },\n      ),\n    ).toBeFalsy();\n\n    expect(\n      deepEqual(\n        { first: { value: 1 }, second: { value: 2 } },\n        { first: shared, second: shared },\n      ),\n    ).toBeFalsy();\n\n    expect(\n      deepEqual([shared, shared], [{ value: 1 }, { value: 9 }]),\n    ).toBeFalsy();\n\n    expect(\n      deepEqual(\n        { first: shared, second: shared },\n        { first: { value: 1 }, second: { value: 1 } },\n      ),\n    ).toBeTruthy();\n  });\n\n  it('should return true when comparing NaN values', () => {\n    expect(deepEqual(NaN, NaN)).toBeTruthy();\n\n    // Object NaN\n    expect(deepEqual({ value: NaN }, { value: NaN })).toBeTruthy();\n\n    // Array NaN\n    expect(deepEqual([NaN], [NaN])).toBeTruthy();\n\n    // Nested Structures NaN\n    expect(\n      deepEqual(\n        { user: { age: NaN, name: 'test' } },\n        { user: { age: NaN, name: 'test' } },\n      ),\n    ).toBeTruthy();\n\n    // Mixed with other values\n    expect(\n      deepEqual({ a: NaN, b: 1, c: 'test' }, { a: NaN, b: 1, c: 'test' }),\n    ).toBeTruthy();\n  });\n\n  it('should return false when comparing NaN with other values', () => {\n    expect(deepEqual({ value: NaN }, { value: 0 })).toBeFalsy();\n    expect(deepEqual({ value: NaN }, { value: undefined })).toBeFalsy();\n    expect(deepEqual({ value: NaN }, { value: null })).toBeFalsy();\n    expect(deepEqual({ value: NaN }, { value: 'NaN' })).toBeFalsy();\n    expect(deepEqual([NaN], [0])).toBeFalsy();\n  });\n\n  it('should compare empty non-plain objects by reference', () => {\n    class EmptyObject {}\n\n    const file = new File(['a'], 'a.svg', { type: 'image/svg+xml' });\n\n    expect(deepEqual(file, file)).toBeTruthy();\n    expect(\n      deepEqual(file, new File(['b'], 'b.jpg', { type: 'image/jpeg' })),\n    ).toBeFalsy();\n    expect(deepEqual(new Blob(['a']), new Blob(['a']))).toBeFalsy();\n    expect(deepEqual(new FormData(), new FormData())).toBeFalsy();\n    expect(\n      deepEqual(new Map([['test', '1']]), new Map([['test', '1']])),\n    ).toBeFalsy();\n    expect(deepEqual(new Set(['test']), new Set(['test']))).toBeFalsy();\n    expect(deepEqual(new EmptyObject(), new EmptyObject())).toBeFalsy();\n  });\n});\n"],"names":["describe","it","expect","deepEqual","test","toBeFalsy","test1","Date","unknown","undefined","userName","fruit","break","name","toBeTruthy","nestedArray","sparseArray","plainObject","items","a","b","self","other","parent","shared","value","first","second","NaN","user","age","c","EmptyObject","file","File","type","Blob","FormData","Map","Set"],"mappings":";;;;kEAAsB;;;;;;AAEtBA,SAAS,aAAa;IACpBC,GAAG,+CAA+C;QAChDC,OACEC,IAAAA,kBAAS,EAAC;YAAC;gBAAEC,MAAM;YAAM;YAAG;gBAAEA,MAAM;YAAM;YAAG;gBAAEA,MAAM;YAAM;SAAE,EAAE,EAAE,GACjEC,SAAS;QAEXH,OACEC,IAAAA,kBAAS,EACP;YAAC;gBAAEC,MAAM;YAAM;YAAG;gBAAEA,MAAM;YAAM;YAAG;gBAAEA,MAAM;YAAM;SAAE,EACnD;YAAC;gBAAEA,MAAM;YAAM;YAAG;gBAAEA,MAAM;YAAM;YAAG;gBAAEA,MAAM;gBAAOE,OAAO;YAAO;SAAE,GAEpED,SAAS;QAEXH,OAAOC,IAAAA,kBAAS,EAAC;YAAC,CAAC;SAAE,EAAE,EAAE,GAAGE,SAAS;QAErCH,OAAOC,IAAAA,kBAAS,EAAC,EAAE,EAAE;YAAC,CAAC;SAAE,GAAGE,SAAS;QACrCH,OAAOC,IAAAA,kBAAS,EAAC,IAAII,QAAQ,IAAIA,KAAK,UAAUF,SAAS;QAEzDH,OACEC,IAAAA,kBAAS,EACP;YACEK,SAASC;YACTC,UAAU;YACVC,OAAO;QACT,GACA;YACED,UAAU;YACVC,OAAO;YACPC,OAAO,CAAC;QACV,IAEFP,SAAS;IACb;IAEAJ,GAAG,qDAAqD;QACtDC,OAAOC,IAAAA,kBAAS,EAAC,MAAM,EAAE,GAAGE,SAAS;QACrCH,OAAOC,IAAAA,kBAAS,EAAC,EAAE,EAAE,OAAOE,SAAS;QACrCH,OAAOC,IAAAA,kBAAS,EAAC,CAAC,GAAGM,YAAYJ,SAAS;QAC1CH,OAAOC,IAAAA,kBAAS,EAACM,WAAW,CAAC,IAAIJ,SAAS;IAC5C;IAEAJ,GAAG,4CAA4C;QAC7CC,OACEC,IAAAA,kBAAS,EAAC;YAAC;gBAAEU,MAAM;YAAgB;SAAE,EAAE;YAAC;gBAAEA,MAAM;YAAgB;SAAE,GAClEC,UAAU;QAEZZ,OACEC,IAAAA